import { BulkEditField } from 'app/shared/toolkit/bulk-edit/bulk-edit.model';
import { BaseBulkEditAction } from 'app/shared/toolkit/action/base-bulk-edit-action';
import { TemplateAsset } from 'app/features/template/template-asset/model/template-asset.model';
import { TemplateAssetRepository } from 'app/features/template/template-asset/repository/template-asset-repository.service';
import { BulkEditDialogData } from 'app/shared/toolkit/bulk-edit/bulk-edit-dialog.component';
import { Component, inject } from '@angular/core';

/** Edición masiva de template asset: los campos que se pueden cambiar en bloque. */
@Component({ selector: 'template-asset-view-bulk-edit-action', standalone: false, template: '' })
export class TemplateAssetViewBulkEditActionComponent extends BaseBulkEditAction<TemplateAsset> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'template/template-asset';
  protected readonly repository = inject(TemplateAssetRepository);

  protected override keyOf(item: TemplateAsset): string {
    return String(item.uid);
  }

  /** Los campos que se pueden editar en bloque y el tipo de cada uno. */
  protected bulkFields(): readonly BulkEditField<TemplateAsset>[] {
    return [
      { name: 'tenant', label: this.text('fieldTenant'), type: 'relation', optional: true },
      { name: 'code', label: this.text('fieldCode'), type: 'text' },
      { name: 'type', label: this.text('fieldType'), type: 'text' },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<TemplateAsset> {
    return {
      title: this.text('dialogTitle'),
      count,
      singular: this.text('selectedSingular'),
      plural: this.text('selectedPlural'),
      confirm: this.text('confirm'),
      cancel: this.text('cancel'),
      fields: this.bulkFields(),
    };
  }
}
